def handle_oom_error(func, *args, **kwargs):
    try:
        return func(*args, **kwargs)
    except torch.cuda.OutOfMemoryError as e:
        logging.error(f'CUDA Out of Memory Error: {e}')
        torch.cuda.empty_cache()
        logging.info('CUDA cache cleared. Trying again with smaller batch size.')
        # Implement logic to reduce batch size or use gradient accumulation
        return None  # Or re-raise the exception if necessary
    except Exception as e:
        logging.error(f'An unexpected error occurred: {e}')
        return None
